interface TreeNode {
  left: TreeNode | null;
  right: TreeNode | null;
}

function bottomUpTree(depth: number): TreeNode {
  if (depth === 0) {
    return { left: null, right: null };
  }

  return {
    left: bottomUpTree(depth - 1),
    right: bottomUpTree(depth - 1)
  };
}

function itemCheck(tree: TreeNode): number {
  if (tree.left === null || tree.right === null) {
    return 1;
  }

  return 1 + itemCheck(tree.left) + itemCheck(tree.right);
}

function buildAndCheck(depth: number): number {
  return itemCheck(bottomUpTree(depth));
}

function main(): void {
  const n = parseInt(process.argv[2], 10);
  const lines: string[] = [];

  const stretchCheck = buildAndCheck(n + 1);
  lines.push(`stretch tree of depth ${n + 1}\t check: ${stretchCheck}`);

  const longLivedTree = bottomUpTree(n);

  for (let depth = 4; depth <= n; depth += 2) {
    const treeCount = Math.pow(2, n - depth + 4);
    let check = 0;

    for (let i = 0; i < treeCount; i++) {
      check += buildAndCheck(depth);
    }

    lines.push(`${treeCount}\t trees of depth ${depth}\t check: ${check}`);
  }

  lines.push(`long lived tree of depth ${n}\t check: ${itemCheck(longLivedTree)}`);
  process.stdout.write(lines.join("\n") + "\n");
}

main();
