function frequencies(k: number): string[] {
  const counts = new Map<string, number>();

  for (let i = 0; i + k <= sequence.length; i++) {
    const fragment = sequence.slice(i, i + k);
    counts.set(fragment, (counts.get(fragment) ?? 0) + 1);
  }

  const entries = Array.from(counts.entries());
  entries.sort((a, b) => {
    const countDifference = b[1] - a[1];
    return countDifference !== 0 ? countDifference : a[0].localeCompare(b[0]);
  });

  const total = sequence.length - k + 1;

  return entries.map(([fragment, count]) => {
    const percentage = total > 0 ? (count * 100) / total : 0;
    return `${fragment} ${percentage.toFixed(3)}`;
  });
}

function countOccurrences(fragment: string): number {
  let count = 0;

  for (let i = 0; i + fragment.length <= sequence.length; i++) {
    if (sequence.startsWith(fragment, i)) {
      count++;
    }
  }

  return count;
}

const output: string[] = [];
