  let flips = 0;
  let k = perm[0];

  while (k !== 0) {
    let left = 0;
    let right = k;

    while (left < right) {
      const value = perm[left];
      perm[left] = perm[right];
      perm[right] = value;
      left++;
      right--;
    }

    flips++;
    k = perm[0];
  }

  if (flips > maxFlips) {
    maxFlips = flips;
  }

  if ((permutationIndex & 1) === 0) {
    checksum += flips;
  } else {
    checksum -= flips;
  }
  permutationIndex++;

